const payload = $json.body ?? $json;
const message = String(payload.message ?? '').trim();
const currentPath = String(payload.currentPath ?? '/');
const sessionId = String(payload.sessionId ?? '');
const history = Array.isArray(payload.history) ? payload.history : [];
const normalized = message.toLowerCase();

const processSteps = [
  '1. Recepcion y alcance del caso.',
  '2. Preservacion de la evidencia digital.',
  '3. Analisis tecnico de artefactos relevantes.',
  '4. Informe verificable con hallazgos y conclusiones.'
].join(' ');

let reply = 'Puedo orientarte sobre metodologia, preservacion, cadena de custodia, alcance del servicio y preparacion inicial del caso. Si tu situacion requiere analisis formal, usa tambien el formulario de contacto.';

if (!message) {
  reply = 'Escribe tu consulta y te orientare sobre los procesos de CyberVestigio.';
} else if (/cadena de custodia|custodia/.test(normalized)) {
  reply = 'La cadena de custodia se orienta a identificar, recibir, documentar, transferir, analizar y entregar la evidencia con trazabilidad. Antes de manipular un dispositivo o cuenta, conviene registrar origen, fecha, responsable, estado y cualquier accion realizada.';
} else if (/preserv|evidencia|integridad|hash/.test(normalized)) {
  reply = 'La preservacion busca evitar alteraciones sobre la evidencia. En terminos generales, se recomienda no seguir usando el dispositivo, documentar el contexto, limitar accesos, conservar metadatos y aplicar controles de integridad como valores hash cuando corresponda.';
} else if (/proceso|metodolog|pasos|etapas/.test(normalized)) {
  reply = `El proceso base de CyberVestigio contempla estas etapas: ${processSteps}`;
} else if (/tiempo|demora|plazo/.test(normalized)) {
  reply = 'Los tiempos dependen del volumen de informacion, tipo de fuente, urgencia y alcance autorizado. Lo mas util es iniciar con una evaluacion del caso para definir evidencia disponible, restricciones y nivel de documentacion requerido.';
} else if (/contact|correo|telefono|cotiz|precio|valor/.test(normalized)) {
  reply = 'Para una evaluacion inicial y definir alcance, usa el formulario de contacto del sitio. Alli puedes describir el caso, la evidencia disponible y el objetivo tecnico o juridico que necesitas sustentar.';
} else if (/whatsapp|llamar|asesor/.test(normalized)) {
  reply = 'Si necesitas orientacion inicial, el canal mas ordenado es el formulario de contacto del sitio. Eso ayuda a registrar contexto, tipo de evidencia y prioridad antes de proponer el siguiente paso.';
} else {
  const pathHint = currentPath !== '/' ? ` Veo que la consulta se hizo desde ${currentPath}.` : '';
  const historyHint = history.length > 0 ? ' Si lo deseas, puedes ampliar con mas contexto del caso, tipo de evidencia o etapa del proceso.' : '';
  reply = `Puedo ayudarte con preguntas sobre metodologia forense, preservacion de evidencia digital, cadena de custodia y documentacion tecnica.${pathHint}${historyHint}`;
}

return [{
  json: {
    reply,
    sessionId,
    source: 'n8n-cybervestigio-chat',
    receivedAt: new Date().toISOString()
  }
}];
